Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define LL long long
#define pb push_back
#define mp make_pair
#define pii pair<int,int>
using namespace std;

inline int read(){
    int v=0,f=1;
    char c=getchar();
    while (c<'0' || c>'9'){
        if (c=='-') f=-1;
        c=getchar();
    }
    while (c>='0' && c<='9'){
        v=v*10+c-'0';
        c=getchar();
    }
    return v*f;
}

const int Maxn=10;
const LL mod=1000000007;

LL power(LL base, LL exp){
    LL result=1;
    while (exp){
        if (exp & 1) result=result*base%mod;
        base=base*base%mod;
        exp>>=1;
    }
    return result;
}

LL modular_inverse(LL x){
    return power(x, mod-2);
}

int p[Maxn][Maxn], n;
int id[64], ki, X[1048576], Y[1048576];

void add_mod(int &x, int y){
    x+=y;
    if (x>=mod) x-=mod;
}

void subtract_mod(int &x, int y){
    x-=y;
    if (x<0) x+=mod;
}

void fast_walsh_transform(int *P, int opt){
    int N=1048576;
    for (int length=2; length<=N; length<<=1){
        for (int start=0; start<N; start+=length){
            for (int k=start; k<start+(length>>1); ++k){
                if (opt==1) add_mod(P[k], P[k+(length>>1)]);
                else subtract_mod(P[k], P[k+(length>>1)]);
            }
        }
    }
}

int main(){
    int n=read();
    for (int i=0; i<n; i++){
        for (int j=0; j<n; j++){
            p[i][j]=1LL*read()*modular_inverse(100)%mod;
        }
    }
    if (n<6){
        for (int i=n; i<6; i++) p[i][i]=1;
        n=6;
    }
    int A=(1<<6)-1;
    for (int i=0; i<64; i++){
        if (__builtin_popcount(i)==3) id[i]=ki++;
    }
    for (int i=0; i<(1<<18); i++){
        int msk1=i&A, msk2=(i>>6)&A, msk3=(i>>12)&A;
        int mask=0;
        LL pp=1;
        for (int j=0; j<6; j++){
            if (msk1>>j&1) pp=pp*p[0][j]%mod;
            else pp=pp*(mod+1-p[0][j])%mod;
        }
        for (int j=0; j<6; j++){
            if (msk2>>j&1) pp=pp*p[1][j]%mod;
            else pp=pp*(mod+1-p[1][j])%mod;
        }
        for (int j=0; j<6; j++){
            if (msk3>>j&1) pp=pp*p[2][j]%mod;
            else pp=pp*(mod+1-p[2][j])%mod;
        }
        if (pp==0) continue;
        for (int a=0; a<6; a++){
            if (msk1>>a&1){
                for (int b=0; b<6; b++){
                    if (a==b) continue;
                    if (msk2>>b&1){
                        for (int c=0; c<6; c++){
                            if (a==c || b==c) continue;
                            if (msk3>>c&1){
                                int nmsk=(1<<a)|(1<<b)|(1<<c);
                                mask|=1<<id[nmsk];
                            }
                        }
                    }
                }
            }
        }
        add_mod(X[mask], int(pp));
    }

    for (int i=0; i<(1<<18); i++){
        int msk1=i&A, msk2=(i>>6)&A, msk3=(i>>12)&A;
        int mask=0;
        LL pp=1;
        for (int j=0; j<6; j++){
            if (msk1>>j&1) pp=pp*p[3][j]%mod;
            else pp=pp*(mod+1-p[3][j])%mod;
        }
        for (int j=0; j<6; j++){
            if (msk2>>j&1) pp=pp*p[4][j]%mod;
            else pp=pp*(mod+1-p[4][j])%mod;
        }
        for (int j=0; j<6; j++){
            if (msk3>>j&1) pp=pp*p[5][j]%mod;
            else pp=pp*(mod+1-p[5][j])%mod;
        }
        if (pp==0) continue;
        for (int a=0; a<6; a++){
            if (msk1>>a&1){
                for (int b=0; b<6; b++){
                    if (a==b) continue;
                    if (msk2>>b&1){
                        for (int c=0; c<6; c++){
                            if (a==c || b==c) continue;
                            if (msk3>>c&1){
                                int nmsk=(1<<a)|(1<<b)|(1<<c);
                                nmsk^=A;
                                mask|=1<<id[nmsk];
                            }
                        }
                    }
                }
            }
        }
        add_mod(Y[mask], int(pp));
    }

    fast_walsh_transform(X, 1);
    fast_walsh_transform(Y, 1);
    for (int i=0; i<1048576; i++){
        X[i]=1LL*X[i]*Y[i]%mod;
    }
    fast_walsh_transform(X, -1);
    int ans=0;
    for (int i=1; i<1048576; i++) add_mod(ans, X[i]);
    printf("%d\n", ans);
    return 0;
}
